const CACHE='balloon-pop-v10';const FILES=['/','/index.html','/style.css','/game.js','/achievements.js','/achievement-definitions.js','/assets/icon-192.png','/assets/icon-512.png','/favicon.ico','/install.js','/assets/atlas.png','/assets/play-balloon.png','/assets/achievements/FIRST_POP.png','/assets/achievements/FIRST_POP-locked.png','/assets/achievements/POP_100.png','/assets/achievements/POP_100-locked.png','/assets/achievements/POP_1000.png','/assets/achievements/POP_1000-locked.png','/assets/achievements/ALL_MODES.png','/assets/achievements/ALL_MODES-locked.png'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(new URL(e.request.url).pathname.startsWith('/releases/'))return;if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('/'):Response.error()))))});
